-- ===== 001_identity.sql =====

BEGIN;
CREATE SCHEMA IF NOT EXISTS identity;
CREATE TABLE IF NOT EXISTS identity.users (
 user_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(100) NOT NULL, email VARCHAR(320) NOT NULL,
 password_hash TEXT NOT NULL, first_name TEXT NOT NULL, last_name TEXT NOT NULL, phone TEXT, preferred_language VARCHAR(10) NOT NULL DEFAULT 'en', status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE','LOCKED')), is_active BOOLEAN NOT NULL DEFAULT true,
 last_login_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0), UNIQUE(username), UNIQUE(email)
);
CREATE TABLE IF NOT EXISTS identity.roles (role_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS identity.permissions (permission_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(120) NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS identity.user_roles (user_id BIGINT NOT NULL REFERENCES identity.users(user_id), role_id BIGINT NOT NULL REFERENCES identity.roles(role_id), assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(), assigned_by BIGINT, PRIMARY KEY(user_id, role_id));
CREATE TABLE IF NOT EXISTS identity.role_permissions (role_id BIGINT NOT NULL REFERENCES identity.roles(role_id), permission_id BIGINT NOT NULL REFERENCES identity.permissions(permission_id), granted_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(role_id, permission_id));
COMMIT;

-- ===== 002_party.sql =====

BEGIN;
CREATE SCHEMA IF NOT EXISTS party;
CREATE TABLE IF NOT EXISTS party.business_entities (entity_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, entity_code VARCHAR(80) NOT NULL UNIQUE, entity_type VARCHAR(20) NOT NULL CHECK(entity_type IN ('PERSON','ORGANIZATION')), legal_name TEXT NOT NULL, display_name TEXT, name TEXT NOT NULL, phone TEXT, email VARCHAR(320), address TEXT, tax_number TEXT, commercial_registration_number TEXT, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE','BLOCKED')), notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS party.entity_roles (entity_id BIGINT NOT NULL REFERENCES party.business_entities(entity_id), role_code VARCHAR(20) NOT NULL CHECK(role_code IN ('CUSTOMER','SUPPLIER','OTHER')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(entity_id, role_code));
CREATE TABLE IF NOT EXISTS party.customer_profiles (entity_id BIGINT PRIMARY KEY REFERENCES party.business_entities(entity_id), customer_type VARCHAR(30) NOT NULL DEFAULT 'REGULAR', credit_limit NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(credit_limit >= 0), payment_terms_days INTEGER NOT NULL DEFAULT 0 CHECK(payment_terms_days >= 0), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE','BLOCKED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS party.supplier_profiles (entity_id BIGINT PRIMARY KEY REFERENCES party.business_entities(entity_id), credit_limit NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(credit_limit >= 0), payment_terms_days INTEGER NOT NULL DEFAULT 0 CHECK(payment_terms_days >= 0), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE','BLOCKED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS party.sales_representatives (representative_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, name TEXT NOT NULL, phone TEXT, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id));
CREATE TABLE IF NOT EXISTS party.representative_companies (representative_id BIGINT NOT NULL REFERENCES party.sales_representatives(representative_id), entity_id BIGINT NOT NULL REFERENCES party.business_entities(entity_id), assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(representative_id, entity_id));
COMMIT;

-- ===== 003_catalog.sql =====

BEGIN;
CREATE SCHEMA IF NOT EXISTS catalog;
CREATE TABLE IF NOT EXISTS catalog.product_categories (category_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, parent_category_id BIGINT REFERENCES catalog.product_categories(category_id), code VARCHAR(80) NOT NULL UNIQUE, name TEXT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog.brands (brand_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, name TEXT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog.units (unit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name TEXT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS catalog.products (product_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_code VARCHAR(100) NOT NULL UNIQUE, barcode VARCHAR(100) UNIQUE, name TEXT NOT NULL, category_id BIGINT REFERENCES catalog.product_categories(category_id), brand_id BIGINT REFERENCES catalog.brands(brand_id), base_unit_id BIGINT REFERENCES catalog.units(unit_id), minimum_stock NUMERIC(19,6) NOT NULL DEFAULT 0 CHECK(minimum_stock >= 0), expiry_required BOOLEAN NOT NULL DEFAULT false, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS catalog.product_units (product_unit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES catalog.products(product_id), unit_id BIGINT NOT NULL REFERENCES catalog.units(unit_id), conversion_factor NUMERIC(19,6) NOT NULL CHECK(conversion_factor > 0), is_default_purchase_unit BOOLEAN NOT NULL DEFAULT false, is_default_sales_unit BOOLEAN NOT NULL DEFAULT false, UNIQUE(product_id, unit_id));
COMMIT;

-- ===== 004_pricing.sql =====

BEGIN;
CREATE SCHEMA IF NOT EXISTS pricing;
CREATE TABLE IF NOT EXISTS pricing.price_lists (price_list_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name TEXT NOT NULL, price_kind VARCHAR(20) NOT NULL CHECK(price_kind IN ('SELLING','PURCHASE')), currency_code CHAR(3) NOT NULL DEFAULT 'USD', is_default BOOLEAN NOT NULL DEFAULT false, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pricing.product_prices (product_price_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, price_list_id BIGINT NOT NULL REFERENCES pricing.price_lists(price_list_id), product_id BIGINT NOT NULL, product_unit_id BIGINT NOT NULL, price NUMERIC(19,4) NOT NULL CHECK(price >= 0), effective_from TIMESTAMPTZ NOT NULL, effective_to TIMESTAMPTZ, created_by BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(effective_to IS NULL OR effective_to > effective_from));
CREATE INDEX IF NOT EXISTS ix_product_prices_lookup ON pricing.product_prices(product_id, product_unit_id, price_list_id, effective_from DESC);
CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE pricing.product_prices ADD CONSTRAINT ex_product_prices_no_overlap EXCLUDE USING gist (price_list_id WITH =, product_id WITH =, product_unit_id WITH =, tstzrange(effective_from, COALESCE(effective_to,'infinity'::timestamptz),'[)') WITH &&);
COMMIT;

-- ===== 005_inventory.sql =====

BEGIN;
CREATE SCHEMA IF NOT EXISTS inventory;
CREATE TABLE IF NOT EXISTS inventory.warehouses (warehouse_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name TEXT NOT NULL, address TEXT, manager_user_id BIGINT, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory.storage_locations (location_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, warehouse_id BIGINT NOT NULL REFERENCES inventory.warehouses(warehouse_id), code VARCHAR(80) NOT NULL, name TEXT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true, UNIQUE(warehouse_id, code));
CREATE TABLE IF NOT EXISTS inventory.inventory_batches (batch_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL, batch_number VARCHAR(100) NOT NULL, expiry_date DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(product_id,batch_number));
CREATE TABLE IF NOT EXISTS inventory.stock_balances (stock_balance_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL, unit_id BIGINT NOT NULL, warehouse_id BIGINT NOT NULL REFERENCES inventory.warehouses(warehouse_id), location_id BIGINT NOT NULL REFERENCES inventory.storage_locations(location_id), batch_id BIGINT REFERENCES inventory.inventory_batches(batch_id), quantity_on_hand NUMERIC(19,6) NOT NULL DEFAULT 0 CHECK(quantity_on_hand >= 0), quantity_reserved NUMERIC(19,6) NOT NULL DEFAULT 0 CHECK(quantity_reserved >= 0), version BIGINT NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(quantity_reserved <= quantity_on_hand), UNIQUE(product_id,unit_id,warehouse_id,location_id,batch_id));
CREATE TABLE IF NOT EXISTS inventory.stock_movements (movement_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL, unit_id BIGINT NOT NULL, warehouse_id BIGINT NOT NULL REFERENCES inventory.warehouses(warehouse_id), location_id BIGINT NOT NULL REFERENCES inventory.storage_locations(location_id), batch_id BIGINT REFERENCES inventory.inventory_batches(batch_id), movement_type VARCHAR(30) NOT NULL CHECK(movement_type IN ('PURCHASE_RECEIPT','SALE','CUSTOMER_RETURN','SUPPLIER_RETURN','ADJUSTMENT','TRANSFER','RESERVATION','RELEASE_RESERVATION')), quantity_delta NUMERIC(19,6) NOT NULL CHECK(quantity_delta <> 0), reference_type VARCHAR(60), reference_id VARCHAR(100), occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), performed_by BIGINT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS inventory.stock_reservations (reservation_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, reservation_number VARCHAR(80) NOT NULL UNIQUE, customer_id BIGINT NOT NULL, reservation_date DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(25) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','CONFIRMED','PARTIALLY_COLLECTED','COLLECTED','CANCELLED','EXPIRED')), payment_status VARCHAR(20) NOT NULL DEFAULT 'UNPAID' CHECK(payment_status IN ('UNPAID','PARTIAL','PAID')), expiry_date DATE, total_amount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(total_amount >= 0), paid_amount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(paid_amount >= 0 AND paid_amount <= total_amount), remaining_amount NUMERIC(19,4) GENERATED ALWAYS AS (total_amount-paid_amount) STORED, notes TEXT, created_by BIGINT NOT NULL, confirmed_by BIGINT, collected_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS inventory.stock_reservation_lines (reservation_line_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, reservation_id BIGINT NOT NULL REFERENCES inventory.stock_reservations(reservation_id), product_id BIGINT NOT NULL, unit_id BIGINT NOT NULL, warehouse_id BIGINT NOT NULL REFERENCES inventory.warehouses(warehouse_id), location_id BIGINT NOT NULL REFERENCES inventory.storage_locations(location_id), batch_id BIGINT REFERENCES inventory.inventory_batches(batch_id), quantity NUMERIC(19,6) NOT NULL CHECK(quantity > 0), collected_quantity NUMERIC(19,6) NOT NULL DEFAULT 0 CHECK(collected_quantity >= 0 AND collected_quantity <= quantity));
CREATE TABLE IF NOT EXISTS inventory.warehouse_receipts (receipt_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, receipt_number VARCHAR(80) NOT NULL UNIQUE, purchase_invoice_id BIGINT, supplier_id BIGINT NOT NULL, warehouse_id BIGINT NOT NULL REFERENCES inventory.warehouses(warehouse_id), location_id BIGINT NOT NULL REFERENCES inventory.storage_locations(location_id), received_by BIGINT NOT NULL, confirmed_by BIGINT, received_at TIMESTAMPTZ NOT NULL DEFAULT now(), status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','CONFIRMED','CANCELLED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory.warehouse_receipt_lines (receipt_line_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, receipt_id BIGINT NOT NULL REFERENCES inventory.warehouse_receipts(receipt_id), product_id BIGINT NOT NULL, unit_id BIGINT NOT NULL, quantity NUMERIC(19,6) NOT NULL CHECK(quantity > 0), bonus_quantity NUMERIC(19,6) NOT NULL DEFAULT 0 CHECK(bonus_quantity >= 0), batch_id BIGINT REFERENCES inventory.inventory_batches(batch_id), expiry_date DATE, purchase_price NUMERIC(19,4) NOT NULL CHECK(purchase_price >= 0), discount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(discount >= 0));
CREATE INDEX IF NOT EXISTS ix_stock_movement_product_date ON inventory.stock_movements(product_id, occurred_at DESC);
COMMIT;

-- ===== 006_procurement.sql =====

BEGIN;
CREATE SCHEMA IF NOT EXISTS procurement;
CREATE TABLE IF NOT EXISTS procurement.purchase_invoices (purchase_invoice_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, invoice_number VARCHAR(80) NOT NULL UNIQUE, supplier_invoice_number VARCHAR(80), supplier_id BIGINT NOT NULL, invoice_date DATE NOT NULL, due_date DATE, warehouse_id BIGINT NOT NULL, subtotal NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(subtotal >= 0), discount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(discount >= 0), tax NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(tax >= 0), total NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(total >= 0), currency_code CHAR(3) NOT NULL DEFAULT 'USD', status VARCHAR(25) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','CONFIRMED','PARTIALLY_PAID','PAID','CANCELLED','PARTIALLY_RETURNED','RETURNED')), payment_status VARCHAR(20) NOT NULL DEFAULT 'UNPAID' CHECK(payment_status IN ('UNPAID','PARTIAL','PAID')), created_by BIGINT NOT NULL, confirmed_by BIGINT, confirmed_at TIMESTAMPTZ, cancelled_at TIMESTAMPTZ, cancelled_by BIGINT, cancellation_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0, CHECK(due_date IS NULL OR due_date >= invoice_date));
CREATE TABLE IF NOT EXISTS procurement.purchase_invoice_lines (purchase_invoice_line_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, purchase_invoice_id BIGINT NOT NULL REFERENCES procurement.purchase_invoices(purchase_invoice_id), product_id BIGINT NOT NULL, unit_id BIGINT NOT NULL, quantity NUMERIC(19,6) NOT NULL CHECK(quantity > 0), bonus_quantity NUMERIC(19,6) NOT NULL DEFAULT 0 CHECK(bonus_quantity >= 0), unit_price NUMERIC(19,4) NOT NULL CHECK(unit_price >= 0), discount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(discount >= 0), tax NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(tax >= 0), line_total NUMERIC(19,4) NOT NULL CHECK(line_total >= 0));
COMMIT;

-- ===== 007_sales.sql =====

BEGIN;
CREATE SCHEMA IF NOT EXISTS sales;
CREATE TABLE IF NOT EXISTS sales.sales_invoices (sales_invoice_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, invoice_number VARCHAR(80) NOT NULL UNIQUE, customer_id BIGINT NOT NULL, invoice_date DATE NOT NULL, due_date DATE, warehouse_id BIGINT NOT NULL, subtotal NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(subtotal >= 0), discount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(discount >= 0), tax NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(tax >= 0), total NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(total >= 0), paid_amount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(paid_amount >= 0 AND paid_amount <= total), remaining_amount NUMERIC(19,4) GENERATED ALWAYS AS (total-paid_amount) STORED, currency_code CHAR(3) NOT NULL DEFAULT 'USD', sale_type VARCHAR(20) NOT NULL DEFAULT 'RETAIL' CHECK(sale_type IN ('RETAIL','WHOLESALE')), payment_type VARCHAR(20) NOT NULL DEFAULT 'CASH' CHECK(payment_type IN ('CASH','CREDIT','PARTIAL')), status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','CONFIRMED','CANCELLED','REVERSED')), payment_status VARCHAR(20) NOT NULL DEFAULT 'UNPAID' CHECK(payment_status IN ('UNPAID','PARTIAL','PAID')), created_by BIGINT NOT NULL, confirmed_by BIGINT, confirmed_at TIMESTAMPTZ, cancelled_at TIMESTAMPTZ, cancelled_by BIGINT, cancellation_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0, CHECK(due_date IS NULL OR due_date >= invoice_date));
CREATE TABLE IF NOT EXISTS sales.sales_invoice_lines (sales_invoice_line_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sales_invoice_id BIGINT NOT NULL REFERENCES sales.sales_invoices(sales_invoice_id), product_id BIGINT NOT NULL, unit_id BIGINT NOT NULL, quantity NUMERIC(19,6) NOT NULL CHECK(quantity > 0), unit_price NUMERIC(19,4) NOT NULL CHECK(unit_price >= 0), discount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(discount >= 0), tax NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(tax >= 0), line_total NUMERIC(19,4) NOT NULL CHECK(line_total >= 0));
COMMIT;

-- ===== 008_returns.sql =====

BEGIN;
CREATE SCHEMA IF NOT EXISTS returns;
CREATE TABLE IF NOT EXISTS returns.returns (return_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, return_number VARCHAR(80) NOT NULL UNIQUE, return_type VARCHAR(20) NOT NULL CHECK(return_type IN ('CUSTOMER','SUPPLIER')), source_type VARCHAR(30) NOT NULL CHECK(source_type IN ('SALES_INVOICE','PURCHASE_INVOICE')), source_id BIGINT NOT NULL, entity_id BIGINT NOT NULL, return_date DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','CONFIRMED','CANCELLED')), reason TEXT, total_amount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(total_amount >= 0), processed_by BIGINT, cancelled_at TIMESTAMPTZ, cancelled_by BIGINT, cancellation_reason TEXT, created_by BIGINT NOT NULL, confirmed_by BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS returns.return_lines (return_line_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, return_id BIGINT NOT NULL REFERENCES returns.returns(return_id), product_id BIGINT NOT NULL, unit_id BIGINT NOT NULL, quantity NUMERIC(19,6) NOT NULL CHECK(quantity > 0), unit_price NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(unit_price >= 0), refund_amount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(refund_amount >= 0), reason TEXT, condition_status VARCHAR(20), destination VARCHAR(30) NOT NULL CHECK(destination IN ('RETURN_TO_STOCK','DAMAGED','RETURN_TO_SUPPLIER')));
CREATE TABLE IF NOT EXISTS returns.refunds (refund_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, return_id BIGINT NOT NULL REFERENCES returns.returns(return_id), processed_by BIGINT, refund_type VARCHAR(20) NOT NULL CHECK(refund_type IN ('CASH','ACCOUNT_CREDIT','REPLACEMENT')), payment_method VARCHAR(20), reference_number VARCHAR(100), amount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(amount >= 0), status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','PROCESSED','CANCELLED')), approved_by BIGINT, refund_date TIMESTAMPTZ, processed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
COMMIT;

-- ===== 009_finance.sql =====

BEGIN;
CREATE SCHEMA IF NOT EXISTS finance;
CREATE TABLE IF NOT EXISTS finance.cash_accounts (cash_account_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name TEXT NOT NULL, account_type VARCHAR(20) NOT NULL CHECK(account_type IN ('CASH','BANK','OTHER')), currency_code CHAR(3) NOT NULL DEFAULT 'USD', is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS finance.payments (payment_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, payment_number VARCHAR(80) NOT NULL UNIQUE, payment_type VARCHAR(20) NOT NULL CHECK(payment_type IN ('CUSTOMER','SUPPLIER','REFUND','OTHER')), entity_id BIGINT, recorded_by BIGINT, payment_date DATE NOT NULL DEFAULT CURRENT_DATE, amount NUMERIC(19,4) NOT NULL CHECK(amount > 0), method VARCHAR(20) NOT NULL CHECK(method IN ('CASH','BANK','CARD','TRANSFER','OTHER')), reference_number VARCHAR(100), notes TEXT, cash_account_id BIGINT NOT NULL REFERENCES finance.cash_accounts(cash_account_id), status VARCHAR(20) NOT NULL DEFAULT 'POSTED' CHECK(status IN ('DRAFT','POSTED','CANCELLED')), created_by BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS finance.payment_allocations (payment_allocation_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, payment_id BIGINT NOT NULL REFERENCES finance.payments(payment_id), document_type VARCHAR(30) NOT NULL CHECK(document_type IN ('SALES_INVOICE','PURCHASE_INVOICE','ACCOUNT_CREDIT')), document_id BIGINT NOT NULL, amount NUMERIC(19,4) NOT NULL CHECK(amount > 0), allocated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(payment_id,document_type,document_id));
CREATE TABLE IF NOT EXISTS finance.cash_transactions (cash_transaction_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cash_account_id BIGINT NOT NULL REFERENCES finance.cash_accounts(cash_account_id), recorded_by BIGINT, transaction_type VARCHAR(30) NOT NULL CHECK(transaction_type IN ('CASH_RECEIPT','CASH_PAYMENT','CUSTOMER_PAYMENT','SUPPLIER_PAYMENT','REFUND','EXPENSE','TRANSFER','ADJUSTMENT')), amount NUMERIC(19,4) NOT NULL CHECK(amount > 0), direction CHAR(1) NOT NULL CHECK(direction IN ('D','C')), reference_type VARCHAR(60), reference_id VARCHAR(100), description TEXT, transaction_date TIMESTAMPTZ NOT NULL DEFAULT now(), created_by BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS finance.financial_accounts (financial_account_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name TEXT NOT NULL, account_type VARCHAR(20) NOT NULL CHECK(account_type IN ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE')), parent_account_id BIGINT REFERENCES finance.financial_accounts(financial_account_id), is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS finance.journal_entries (journal_entry_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, entry_number VARCHAR(80) NOT NULL UNIQUE, entry_date DATE NOT NULL DEFAULT CURRENT_DATE, description TEXT NOT NULL, source_type VARCHAR(50), source_id BIGINT, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','POSTED','REVERSED')), posted_by BIGINT, posted_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS finance.journal_lines (journal_line_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, journal_entry_id BIGINT NOT NULL REFERENCES finance.journal_entries(journal_entry_id), financial_account_id BIGINT NOT NULL REFERENCES finance.financial_accounts(financial_account_id), entity_id BIGINT, description TEXT, debit NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(debit >= 0), credit NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(credit >= 0), CHECK((debit = 0 AND credit > 0) OR (credit = 0 AND debit > 0)));
CREATE OR REPLACE FUNCTION finance.assert_balanced_journal(p_entry BIGINT) RETURNS void LANGUAGE plpgsql AS $$ DECLARE d NUMERIC; c NUMERIC; s VARCHAR; BEGIN SELECT COALESCE(sum(debit),0),COALESCE(sum(credit),0) INTO d,c FROM finance.journal_lines WHERE journal_entry_id=p_entry; SELECT status INTO s FROM finance.journal_entries WHERE journal_entry_id=p_entry FOR UPDATE; IF s='POSTED' AND (d=0 OR d<>c) THEN RAISE EXCEPTION 'Journal % is not balanced: debit %, credit %',p_entry,d,c; END IF; END $$;
CREATE OR REPLACE FUNCTION finance.trg_balanced_journal() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM finance.assert_balanced_journal(COALESCE(NEW.journal_entry_id,OLD.journal_entry_id)); RETURN COALESCE(NEW,OLD); END $$;
CREATE CONSTRAINT TRIGGER journal_must_balance AFTER INSERT OR UPDATE ON finance.journal_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance.trg_balanced_journal();
COMMIT;

-- ===== 010_audit.sql =====

BEGIN;
CREATE SCHEMA IF NOT EXISTS audit;
CREATE TABLE IF NOT EXISTS audit.audit_logs (audit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, service_name VARCHAR(100) NOT NULL, user_id BIGINT, action VARCHAR(30) NOT NULL CHECK(action IN ('CREATE','UPDATE','CONFIRM','CANCEL','REFUND','PAYMENT','STATUS_CHANGE','LOGIN','LOGOUT','DELETE_ATTEMPT')), entity_type VARCHAR(100) NOT NULL, entity_id VARCHAR(100) NOT NULL, old_values JSONB, new_values JSONB, reason TEXT, correlation_id UUID, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
COMMIT;

-- ===== 011_integration.sql =====

BEGIN;
CREATE SCHEMA IF NOT EXISTS integration;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS integration.outbox_events (event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_type VARCHAR(100) NOT NULL, aggregate_id VARCHAR(100) NOT NULL, event_type VARCHAR(150) NOT NULL, payload JSONB NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ, retry_count INTEGER NOT NULL DEFAULT 0 CHECK(retry_count >= 0), status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PROCESSING','PUBLISHED','FAILED')), last_error TEXT);
COMMIT;

-- ===== 012_views.sql =====

BEGIN;
CREATE OR REPLACE VIEW inventory.v_current_stock AS SELECT product_id,unit_id,warehouse_id,location_id,batch_id,quantity_on_hand,quantity_reserved,quantity_on_hand-quantity_reserved AS quantity_available FROM inventory.stock_balances;
CREATE OR REPLACE VIEW inventory.v_low_stock AS SELECT p.product_id,p.product_code,p.name,p.minimum_stock,COALESCE(sum(s.quantity_on_hand-s.quantity_reserved),0) quantity_available FROM catalog.products p LEFT JOIN inventory.stock_balances s ON s.product_id=p.product_id GROUP BY p.product_id HAVING COALESCE(sum(s.quantity_on_hand-s.quantity_reserved),0) <= p.minimum_stock;
CREATE OR REPLACE VIEW inventory.v_out_of_stock AS SELECT * FROM inventory.v_low_stock WHERE quantity_available <= 0;
CREATE OR REPLACE VIEW inventory.v_expiring_inventory AS SELECT s.*,b.batch_number,b.expiry_date FROM inventory.stock_balances s JOIN inventory.inventory_batches b USING(batch_id) WHERE b.expiry_date IS NOT NULL;
CREATE OR REPLACE VIEW sales.v_invoice_outstanding AS SELECT i.sales_invoice_id,i.invoice_number,i.customer_id,i.total,COALESCE(sum(pa.amount),0) paid,i.total-COALESCE(sum(pa.amount),0) outstanding FROM sales.sales_invoices i LEFT JOIN finance.payment_allocations pa ON pa.document_type='SALES_INVOICE' AND pa.document_id=i.sales_invoice_id GROUP BY i.sales_invoice_id;
CREATE OR REPLACE VIEW procurement.v_invoice_outstanding AS SELECT i.purchase_invoice_id,i.invoice_number,i.supplier_id,i.total,COALESCE(sum(pa.amount),0) paid,i.total-COALESCE(sum(pa.amount),0) outstanding FROM procurement.purchase_invoices i LEFT JOIN finance.payment_allocations pa ON pa.document_type='PURCHASE_INVOICE' AND pa.document_id=i.purchase_invoice_id GROUP BY i.purchase_invoice_id;
CREATE OR REPLACE VIEW sales.v_sales_summary AS SELECT invoice_date,count(*) invoice_count,sum(subtotal) subtotal,sum(discount) discount,sum(tax) tax,sum(total) total FROM sales.sales_invoices WHERE status='CONFIRMED' GROUP BY invoice_date;
CREATE OR REPLACE VIEW procurement.v_purchase_summary AS SELECT invoice_date,count(*) invoice_count,sum(total) total FROM procurement.purchase_invoices WHERE status NOT IN ('CANCELLED') GROUP BY invoice_date;
CREATE OR REPLACE VIEW pricing.v_price_history AS SELECT * FROM pricing.product_prices;
CREATE OR REPLACE VIEW finance.v_cash_movement AS SELECT cash_account_id,transaction_date::date transaction_date,sum(CASE WHEN direction='D' THEN amount ELSE 0 END) debits,sum(CASE WHEN direction='C' THEN amount ELSE 0 END) credits FROM finance.cash_transactions GROUP BY cash_account_id,transaction_date::date;
CREATE OR REPLACE VIEW finance.v_detailed_cash_movement AS SELECT * FROM finance.cash_transactions;
CREATE OR REPLACE VIEW inventory.v_reservations AS SELECT r.*,rl.product_id,rl.unit_id,rl.quantity,rl.collected_quantity FROM inventory.stock_reservations r JOIN inventory.stock_reservation_lines rl USING(reservation_id);
CREATE OR REPLACE VIEW returns.v_returns AS SELECT r.*,rl.product_id,rl.unit_id,rl.quantity,rl.destination FROM returns.returns r JOIN returns.return_lines rl USING(return_id);
CREATE OR REPLACE VIEW returns.v_refunds AS SELECT * FROM returns.refunds;
CREATE OR REPLACE VIEW sales.v_product_sales AS SELECT l.product_id,sum(l.quantity) quantity,sum(l.line_total) total FROM sales.sales_invoice_lines l JOIN sales.sales_invoices i USING(sales_invoice_id) WHERE i.status='CONFIRMED' GROUP BY l.product_id;
CREATE OR REPLACE VIEW procurement.v_product_purchases AS SELECT l.product_id,sum(l.quantity+l.bonus_quantity) quantity,sum(l.line_total) total FROM procurement.purchase_invoice_lines l JOIN procurement.purchase_invoices i USING(purchase_invoice_id) WHERE i.status<>'CANCELLED' GROUP BY l.product_id;
CREATE OR REPLACE VIEW finance.v_customer_balance AS SELECT entity_id,sum(CASE WHEN payment_type='CUSTOMER' THEN -amount ELSE 0 END) balance FROM finance.payments WHERE status='POSTED' GROUP BY entity_id;
CREATE OR REPLACE VIEW finance.v_supplier_balance AS SELECT entity_id,sum(CASE WHEN payment_type='SUPPLIER' THEN -amount ELSE 0 END) balance FROM finance.payments WHERE status='POSTED' GROUP BY entity_id;
CREATE OR REPLACE VIEW finance.v_customer_statement AS SELECT entity_id,payment_date statement_date,payment_number reference, 'PAYMENT' entry_type, -amount amount FROM finance.payments WHERE payment_type='CUSTOMER' AND status='POSTED';
CREATE OR REPLACE VIEW finance.v_supplier_statement AS SELECT entity_id,payment_date statement_date,payment_number reference, 'PAYMENT' entry_type, -amount amount FROM finance.payments WHERE payment_type='SUPPLIER' AND status='POSTED';
COMMIT;

-- ===== 013_indexes.sql =====

BEGIN;
CREATE INDEX IF NOT EXISTS ix_users_active ON identity.users(is_active); CREATE INDEX IF NOT EXISTS ix_entities_name ON party.business_entities(name); CREATE INDEX IF NOT EXISTS ix_entities_phone ON party.business_entities(phone); CREATE INDEX IF NOT EXISTS ix_entities_email ON party.business_entities(email);
CREATE UNIQUE INDEX IF NOT EXISTS ux_stock_balance_natural_key ON inventory.stock_balances(product_id,unit_id,warehouse_id,location_id,COALESCE(batch_id,0));
CREATE UNIQUE INDEX IF NOT EXISTS ux_default_purchase_unit ON catalog.product_units(product_id) WHERE is_default_purchase_unit;
CREATE UNIQUE INDEX IF NOT EXISTS ux_default_sales_unit ON catalog.product_units(product_id) WHERE is_default_sales_unit;
CREATE INDEX IF NOT EXISTS ix_products_name ON catalog.products USING gin(to_tsvector('simple',name)); CREATE INDEX IF NOT EXISTS ix_stock_lookup ON inventory.stock_balances(product_id,warehouse_id,location_id); CREATE INDEX IF NOT EXISTS ix_stock_res_status ON inventory.stock_reservations(status); CREATE INDEX IF NOT EXISTS ix_sales_date_status ON sales.sales_invoices(invoice_date,status); CREATE INDEX IF NOT EXISTS ix_purchase_date_status ON procurement.purchase_invoices(invoice_date,status); CREATE INDEX IF NOT EXISTS ix_payments_date ON finance.payments(payment_date); CREATE INDEX IF NOT EXISTS ix_audit_entity ON audit.audit_logs(entity_type,entity_id,occurred_at DESC); CREATE INDEX IF NOT EXISTS ix_outbox_pending ON integration.outbox_events(status,occurred_at) WHERE status IN ('PENDING','FAILED');
COMMIT;

